    int M = 28;
    int N = (int)float_n;

    // Compute mean of each column (attribute)
    for (int j = 0; j < M; j++) {
        mean[j] = 0.0;
        for (int i = 0; i < N; i++) {
            mean[j] += data[i][j];
        }
        mean[j] /= float_n;
    }

    // Compute standard deviation of each column (attribute)
    for (j = 0; j < M; j++) {
        stddev[j] = 0.0;
        for (i = 0; i < N; i++) {
            stddev[j] += (data[i][j] - mean[j]) * (data[i][j] - mean[j]);
        }
        stddev[j] = sqrt(stddev[j] / float_n);
    }

    // Normalize the data
    for (j = 0; j < M; j++) {
        for (i = 0; i < N; i++) {
            if (stddev[j] != 0.0) {
                data[i][j] = (data[i][j] - mean[j]) / stddev[j];
